// MCP tools for batch 49 (31-Oct-2026): print + production helpers for designers and agents.
// Pure cores come from src/tools_core49.js (generated by gen_tools_core.py from tool-gap-2026-10/newtools/*) — one source of
// truth with the /tools/ pages. Stateless: no D1/R2, no fetch, no paid APIs.
import { MGDPaper, MGDPaperSizes, MGDStoryboard, MGDLlmsTxt } from "./tools_core49.js";

const T = "https://madegooddesigns.com/tools";
const ok = (text, structuredContent) => (structuredContent ? { content: [{ type: "text", text }], structuredContent } : { content: [{ type: "text", text }] });
const err = (text) => ({ content: [{ type: "text", text }], isError: true });
const str = (x, max) => (typeof x === "string" ? x : x == null ? "" : String(x)).slice(0, max);
const int = (x, d, lo, hi) => { const n = parseInt(x, 10); return Number.isFinite(n) ? Math.max(lo, Math.min(hi, n)) : d; };
const RO = (title) => ({ title, readOnlyHint: true, destructiveHint: false, openWorldHint: false });
const fence = (lang, s) => "```" + lang + "\n" + String(s).replace(/\n$/, "") + "\n```";
const PAPER_IDS = ["letter", "legal", "tabloid", "ledger", "half-letter", "a3", "a4", "a5", "b5"];
const GRID_SLUG = { graph: "graph-paper", engineering: "graph-paper", hex: "graph-paper", dot: "dot-grid-paper", isometric: "isometric-graph-paper", "iso-dot": "isometric-graph-paper", lined: "lined-paper" };

