// ---- paper sizes ------------------------------------------------------------------------------------------------
function fmtRow(r, unit, dpi, o) {
  const c = MGDPaperSizes.convert(r, unit, { dpi, orientation: o });
  return `| ${r.name} | ${r.family} | ${c.text} | ${r.common_use || ""} |`;
}
function paperSizes(a) {
  const unit = ["mm", "cm", "in", "pt", "px"].includes(a.unit) ? a.unit : "mm";
  const dpi = Number.isFinite(Number(a.dpi)) ? Math.max(36, Math.min(2400, Number(a.dpi))) : 300;
  const o = a.orientation === "landscape" ? "landscape" : "portrait";
  const q = str(a.query, 80).trim(), fam = str(a.family, 30).trim();
  const exact = q ? MGDPaperSizes.get(q) : null;
  let rows = exact && !fam ? [exact] : MGDPaperSizes.find({ query: exact ? "" : q, family: fam || undefined, limit: int(a.limit, 20, 1, 80) });
  if (!rows.length && q) return err(`No paper size matches "${q}". Try a name (A4, letter, legal, tabloid, jis b5, #10, 4x6) or dimensions like 8.5x11 or 210 x 297 mm.`);
  if (!rows.length) rows = MGDPaperSizes.find({ limit: int(a.limit, 20, 1, 80) });
  const parts = [];
  if (rows.length === 1) {
    const r = rows[0], px = MGDPaperSizes.px(r, dpi, o), fr = MGDPaperSizes.figmaFrame(r, 72, o);
    parts.push(`**${r.name}** (${r.series || r.family}): ${r.w_mm} × ${r.h_mm} mm = ${r.w_in} × ${r.h_in} in = ${r.w_pt} × ${r.h_pt} pt (portrait). At ${dpi} DPI: ${px.w} × ${px.h} px (${o}). ${r.common_use || ""}`);
    parts.push("CSS:\n" + fence("css", MGDPaperSizes.cssPage(r, o, "")));
    parts.push(`Design-app frame at 72 DPI: ${fr.width} × ${fr.height}${fr.note ? " — " + fr.note : ""}.`);
    const src = MGDPaperSizes.SOURCES[r.source_id]; if (src) parts.push(`Source: ${src.title} ${src.url}`);
  } else {
    parts.push(`${rows.length} paper size(s)${fam ? " in " + fam : ""}, ${o}, in ${unit}${unit === "px" ? " at " + dpi + " DPI" : ""}:\n\n| Size | Family | Dimensions | Common use |\n|---|---|---|---|\n` + rows.map((r) => fmtRow(r, unit, dpi, o)).join("\n"));
  }
  let cmp = null;
  if (a.compare_with) {
    const b = MGDPaperSizes.get(str(a.compare_with, 80));
    if (!b) parts.push(`(compare_with "${str(a.compare_with, 80)}" not recognised)`);
    else { cmp = MGDPaperSizes.compare(rows[0], b); parts.push(cmp.text); }
  }
  parts.push(`ISO A sizes come from halving the long side of the previous size and rounding DOWN to a whole mm (A1 = 594 × 841). Inch values of metric sizes are derived. Full chart with scaled comparison: ${T}/paper-sizes/`);
  return ok(parts.join("\n\n"), { sizes: rows.map((r) => ({ id: r.id, name: r.name, family: r.family, w_mm: r.w_mm, h_mm: r.h_mm, w_in: r.w_in, h_in: r.h_in, w_pt: r.w_pt, h_pt: r.h_pt, px: MGDPaperSizes.px(r, dpi, o), source: (MGDPaperSizes.SOURCES[r.source_id] || {}).url || null })), compare: cmp });
}

// ---- grid paper -------------------------------------------------------------------------------------------------
function gridPaper(a) {
  const spec = { type: a.type || "graph", paper: PAPER_IDS.includes(a.paper) ? a.paper : "letter" };
  if (a.orientation) spec.orientation = a.orientation === "landscape" ? "landscape" : "portrait";
  if (a.unit === "mm" || a.unit === "in") spec.unit = a.unit;
  if (a.spacing != null) spec.spacing = typeof a.spacing === "number" ? a.spacing : str(a.spacing, 12);
  if (a.major_every != null) spec.majorEvery = int(a.major_every, 0, 0, 20);
  if (a.rule) spec.rule = a.rule;
  if (a.header) spec.header = a.header;
  if (a.line_color && /^#[0-9a-f]{3,8}$/i.test(str(a.line_color, 9))) { spec.lineColor = a.line_color; spec.majorColor = a.line_color; }
  if (spec.type === "engineering") spec.preset = "engineering";
  const model = MGDPaper.build(spec), svg = MGDPaper.svg(model), desc = MGDPaper.describe(model);
  const warn = model.warnings || [];
  const slug = GRID_SLUG[model.meta.type] || "graph-paper";
  const text = `${desc}.${warn.length ? "\nNote: " + [...new Set(warn)].join("; ") : ""}\n\nTrue-size SVG (print at 100% / Actual size):\n${fence("svg", svg)}\n\nMulti-page vector PDF and PNG with the same settings: ${T}/${slug}/`;
  return ok(text, { svg, meta: model.meta, width_pt: model.widthPt, height_pt: model.heightPt });
}

// ---- storyboard -------------------------------------------------------------------------------------------------
function storyboard(a) {
  const raw = typeof a.shots === "string" ? a.shots.split(/\n+/).map((s) => s.trim()).filter(Boolean) : Array.isArray(a.shots) ? a.shots : [];
  if (!raw.length) return err("Pass shots: a list of {scene, shot_type, camera, duration, action, dialogue} objects or one line per shot.");
  const shots = MGDStoryboard.normalizeShots(raw.slice(0, 120));
  const lay = MGDStoryboard.layout({ paper: a.paper === "a4" ? "a4" : "letter", orientation: a.orientation === "portrait" ? "portrait" : "landscape", aspect: a.aspect || "16:9", perPage: int(a.per_page, 6, 2, 9) });
  const title = str(a.title, 120);
  const svgs = a.svg === false ? [] : MGDStoryboard.svg(lay, shots, { title });
  const md = MGDStoryboard.markdown(shots), csv = MGDStoryboard.csv(shots);
  const tot = MGDStoryboard.totals(shots), total = tot.seconds;
  const parts = [`Storyboard${title ? " for " + title : ""}: ${shots.length} shot(s), ${svgs.length || Math.ceil(shots.length / (lay.perPage || 6))} page(s), total running time ${tot.label}${tot.timed < shots.length ? ` (${shots.length - tot.timed} shot(s) without a duration)` : ""}.`, "Shot list:\n" + md];
  svgs.slice(0, 6).forEach((s, i) => parts.push(`Page ${i + 1} (SVG):\n` + fence("svg", s)));
  if (svgs.length > 6) parts.push(`(${svgs.length - 6} more page(s) in structuredContent.svg_pages)`);
  parts.push(`Add images or sketches per frame and export a PDF: ${T}/storyboard-template/ · turn it into comic panels: ${T}/comic-strip-maker/`);
  return ok(parts.join("\n\n"), { shots, svg_pages: svgs, markdown: md, csv, total_seconds: total });
}

// ---- llms.txt ---------------------------------------------------------------------------------------------------
function llmsTxt(a) {
  const show = (rep) => rep.findings.length ? rep.findings.slice(0, 60).map((f) => `- ${f.level}${f.line ? " (line " + f.line + ")" : ""} [${f.source}] ${f.rule}: ${f.message}`).join("\n") : "No findings.";
  if (a.lint != null) {
    const t = str(a.lint, 200000); const rep = MGDLlmsTxt.report(t);
    return ok(`llms.txt check: ${rep.errors} error(s), ${rep.warnings} warning(s), ${rep.infos} tip(s) — ${rep.stats.sections} section(s), ${rep.stats.links} link(s).\n[spec] = llmstxt.org rule, [parser] = reference parser behaviour, [advice] = our suggestion.\n\n${show(rep)}\n\nFix it in the browser: ${T}/llms-txt-generator/`, { report: rep });
  }
  if (!str(a.title, 200).trim()) return err("Pass title (the required H1), plus summary and sections — or pass lint with an existing llms.txt to validate.");
  const text = MGDLlmsTxt.build({ title: str(a.title, 200), summary: str(a.summary, 2000), details: str(a.details, 8000), sections: Array.isArray(a.sections) ? a.sections.slice(0, 40) : [], optional: Array.isArray(a.optional) ? a.optional.slice(0, 200) : [] });
  const rep = MGDLlmsTxt.report(text);
  return ok(`llms.txt (${rep.stats.sections} section(s), ${rep.stats.links} link(s); check: ${rep.errors} error(s), ${rep.warnings} warning(s)). Serve it at /llms.txt (or a subpath it covers) as text/plain or text/markdown.\n\n${fence("markdown", text)}\n\n${rep.findings.length ? show(rep) + "\n\n" : ""}Edit, import a sitemap or validate: ${T}/llms-txt-generator/`, { llms_txt: text, report: rep });
}

// ---------------------------------------------------------------------------------------------------------------------
const NAMES = new Set(TOOL_DEFS.map((t) => t.name));
export function isTools49Tool(name) { return NAMES.has(name); }

export async function callTools49Tool(name, a) {
  a = a || {};
  try {
    if (name === "get_paper_sizes") return paperSizes(a);
    if (name === "make_grid_paper") return gridPaper(a);
    if (name === "make_storyboard") return storyboard(a);
    if (name === "generate_llms_txt") return llmsTxt(a);
  } catch (e) {
    return err(`${name} failed: ${str(e && e.message, 300)}`);
  }
  return err("Unknown tool: " + name);
}

